package com.pratik.imagetap;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.Executor;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,qualifiers="w412dp-h892dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class Release67Test {
 @Before public void disableMotion(){RuntimeEnvironment.getApplication().getSharedPreferences("config",0).edit().putBoolean("reduceMotion",true).commit();}
 @Test public void enabledHeadersGlowWithoutReplacingListener(){ActiveSwitch s=new ActiveSwitch(RuntimeEnvironment.getApplication());s.setText("Touch pulse");Ui.polish(s);final boolean[] observed={false};s.setOnCheckedChangeListener((v,on)->observed[0]=on);s.setChecked(true);assertTrue(observed[0]);assertEquals(Ui.GREEN,s.getCurrentTextColor());assertTrue(s.getShadowRadius()>0);s.setChecked(false);assertFalse(observed[0]);assertEquals(0,s.getShadowRadius(),0);assertEquals(Ui.TEXT,s.getCurrentTextColor());}
 @Test public void pulseSliderReachesOneTenth()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().get();tab(a,3);views(root(a),SeekBar.class).get(0).setProgress(0);assertEquals(100,a.getSharedPreferences("config",0).getInt("pulseMs",0));assertNotNull(AutoBashUiTest.find(root(a),"0.1 s"));a.finish();}
 @Test public void sixTargetsUseThreeColumnTilesAndKeepActions()throws Exception{Context c=RuntimeEnvironment.getApplication();for(int i=0;i<6;i++){Bitmap b=Bitmap.createBitmap(40,40,Bitmap.Config.ARGB_8888);b.eraseColor(Color.rgb(30+i*25,80,110));TargetStore.save(c,b);b.recycle();}MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().get();tab(a,1);AutoBashUiTest.save(root(a),"targets-grid67",824,1656);List<LinearLayout> tiles=new ArrayList<>();for(LinearLayout l:views(root(a),LinearLayout.class))if("target-tile".equals(l.getTag()))tiles.add(l);assertEquals(6,tiles.size());assertSame(tiles.get(0).getParent(),tiles.get(1).getParent());assertNotSame(tiles.get(0).getParent(),tiles.get(3).getParent());assertEquals(3,((ViewGroup)tiles.get(0).getParent()).getChildCount());assertEquals("Delete target 1",views(tiles.get(0),Button.class).get(0).getContentDescription());tiles.get(0).performClick();assertNotNull(AutoBashUiTest.find(org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().getWindow().getDecorView(),"Include in scans"));a.finish();}
 @Test public void duplicateSliderIncludes80And100(){Activity a=Robolectric.buildActivity(MainActivity.class).setup().get();DuplicateTool tool=new DuplicateTool(a,()->{});tool.open();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();SeekBar bar=views(d.getWindow().getDecorView(),SeekBar.class).get(0);assertEquals(20,bar.getMax());bar.setProgress(0);assertNotNull(AutoBashUiTest.find(d.getWindow().getDecorView(),"80% · similarity threshold"));bar.setProgress(20);assertNotNull(AutoBashUiTest.find(d.getWindow().getDecorView(),"100% · identical original pixels"));tool.close();a.finish();}
 @Test public void compactLauncherDragsAndStops()throws Exception{TapService svc=service(false);LinearLayout panel=(LinearLayout)get(svc,"panel");assertEquals("compact-launcher",panel.getTag());assertEquals(1,panel.getChildCount());View stop=panel.getChildAt(0);assertTrue(stop instanceof BrainStopView);AutoBashUiTest.save(panel,"compact-launcher67",128,128);WindowManager.LayoutParams lp=(WindowManager.LayoutParams)panel.getLayoutParams();int oldY=lp.y;for(MotionEvent e:new MotionEvent[]{MotionEvent.obtain(0,0,0,25,25,0),MotionEvent.obtain(0,10,2,25,55,0),MotionEvent.obtain(0,20,1,25,55,0)}){stop.dispatchTouchEvent(e);e.recycle();}assertTrue((Boolean)get(svc,"running"));assertTrue(lp.y>oldY);stop.performClick();assertFalse((Boolean)get(svc,"running"));svc.onDestroy();}
 @Test public void launcherPreferenceSwitchesDuringSession()throws Exception{TapService svc=service(false);svc.getSharedPreferences("config",0).edit().putBoolean("detailedLauncher",true).commit();svc.applyLauncherPreference();assertTrue((Boolean)get(svc,"running"));assertNotNull(get(svc,"pauseButton"));svc.getSharedPreferences("config",0).edit().putBoolean("detailedLauncher",false).commit();svc.applyLauncherPreference();assertNull(get(svc,"pauseButton"));assertEquals(1,((LinearLayout)get(svc,"panel")).getChildCount());svc.stopSession("test");svc.onDestroy();}
 @Test public void transferPausePreservesManualPause()throws Exception{TapService svc=service(false);SessionPause pause=(SessionPause)get(svc,"pause");pause.manual=true;svc.beginPresetTransfer();assertTrue(pause.transfer);svc.endPresetTransfer();assertFalse(pause.transfer);assertTrue(pause.manual);svc.stopSession("test");svc.onDestroy();}
 public static class ThrottledService extends TapService {@Override public void takeScreenshot(int display,Executor executor,TakeScreenshotCallback callback){callback.onFailure(ERROR_TAKE_SCREENSHOT_INTERVAL_TIME_SHORT);}}
 @Test public void androidThrottleAdaptsWithoutStopping()throws Exception{ThrottledService svc=Robolectric.buildService(ThrottledService.class).create().get();set(svc,"wm",svc.getSystemService(Context.WINDOW_SERVICE));set(svc,"prefs",svc.getSharedPreferences("config",0));set(svc,"running",true);CaptureGate gate=(CaptureGate)get(svc,"captureGate");int ticket=gate.begin();Method request=TapService.class.getDeclaredMethod("requestScreenshot",int.class,boolean.class,int.class);request.setAccessible(true);request.invoke(svc,0,false,ticket);assertEquals(350,get(svc,"captureFloorMs"));assertEquals(0,get(svc,"failures"));assertFalse(gate.busy());assertTrue((Boolean)get(svc,"running"));svc.stopSession("test");svc.onDestroy();}
 static TapService service(boolean detailed)throws Exception{TapService svc=Robolectric.buildService(TapService.class).create().get();SharedPreferences p=svc.getSharedPreferences("config",0);p.edit().putBoolean("detailedLauncher",detailed).commit();set(svc,"prefs",p);set(svc,"wm",svc.getSystemService(Context.WINDOW_SERVICE));Method m=TapService.class.getDeclaredMethod("showPanel");m.setAccessible(true);m.invoke(svc);set(svc,"running",true);return svc;}
 static Object get(Object o,String n)throws Exception{Field f=TapService.class.getDeclaredField(n);f.setAccessible(true);return f.get(o);}static void set(Object o,String n,Object v)throws Exception{Field f=TapService.class.getDeclaredField(n);f.setAccessible(true);f.set(o,v);}
 static View root(Activity a){return ((ViewGroup)a.findViewById(android.R.id.content)).getChildAt(0);}static void tab(MainActivity a,int n)throws Exception{if(n==1){Field open=MainActivity.class.getDeclaredField("actionCollectionOpen");open.setAccessible(true);open.set(a,true);}Field f=MainActivity.class.getDeclaredField("tab");f.setAccessible(true);f.set(a,n);Method m=MainActivity.class.getDeclaredMethod("render");m.setAccessible(true);m.invoke(a);}
 static <T> List<T> views(View v,Class<T> cls){List<T> out=new ArrayList<>();if(cls.isInstance(v))out.add(cls.cast(v));if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)out.addAll(views(((ViewGroup)v).getChildAt(i),cls));return out;}
}
